M09_INVARIANTS = tuple(InvariantRequirement(*item) for item in _INVARIANT_RECORDS)
M09_INVARIANT_MAP = MappingProxyType({item.number: item for item in M09_INVARIANTS})

def validate_invariant_catalog() -> bool:
    if len(M09_INVARIANTS) != 514 or tuple(item.number for item in M09_INVARIANTS) != tuple(range(1, 515)):
        raise ValueError("M09 invariant catalog must cover exactly 1..514")
    if len({item.proof_id for item in M09_INVARIANTS}) != 514 or len({item.assertion_id for item in M09_INVARIANTS}) != 514:
        raise ValueError("M09 invariant proof identifiers must be unique")
    for item in M09_INVARIANTS:
        expected = hashlib.sha256(f"{item.number}. {item.frozen_text}".encode("utf-8")).hexdigest()
        if item.text_digest != expected or item.proof_target == item.semantic_target:
            raise ValueError(f"M09 invariant {item.number} has invalid text/proof binding")
    return True


def validate_invariant_claim_groups(
    invariants: tuple[InvariantRequirement, ...],
    claim_groups: dict[str, tuple[int, ...]],
) -> tuple[str, ...]:
    """Check exact, unique invariant-ID claims for every shared proof target."""
    failures: list[str] = []
    expected_targets = {item.semantic_target for item in invariants}
    if set(claim_groups) != expected_targets:
        failures.append("proof-claim targets differ from invariant semantic targets")
    seen: set[int] = set()
    for target, claimed in claim_groups.items():
        if type(claimed) is not tuple or any(type(number) is not int for number in claimed):
            failures.append(f"proof target {target} does not use a literal integer tuple")
            continue
        if len(claimed) != len(set(claimed)):
            failures.append(f"proof target {target} duplicates an invariant ID")
        duplicates = seen.intersection(claimed)
        if duplicates:
            failures.append(f"proof target {target} repeats invariant IDs {sorted(duplicates)}")
        seen.update(claimed)
        expected = tuple(item.number for item in invariants if item.semantic_target == target)
        if claimed != expected:
            failures.append(f"proof target {target} claim list differs from exact invariant bindings")
    expected_ids = {item.number for item in invariants}
    if seen != expected_ids:
        failures.append("proof-claim map has missing or orphan invariant IDs")
    return tuple(failures)
